// The critics' final verdicts on run 1 of the wardrobe build (the art
// factory), as data for outfit-gallery.html, the Gate 1 cut sheet.
//
// One entry per item variant (and per Move). `verdict` is "keep" | "fix" | "cut".
// `line` is the one-line reason the gallery tile shows; `reason` is the
// critic's full reasoning and `fix` (fix verdicts only) the change it asked
// for. A fix means the critic judged that art not good enough yet; the tile
// shows the art as it stands on disk now, so check whether the fix has landed.
//
// `unit` is the module the critic judged (metal-kit, pop-show, shared, moves…);
// `genre` is the page it belongs to ("shared" items are judged once and shown
// on all four genres; Moves carry the genre of the Move).

const UNIT_GENRE = {
  "metal-kit": "metal",
  "metal-show": "metal",
  "pop-kit": "pop",
  "pop-show": "pop",
  "country-kit": "country",
  "country-show": "country",
  "disco-kit": "disco",
  "disco-show": "disco",
  shared: "shared"
};

const MOVE_GENRE = {
  "horns-pump": "metal",
  "double-headbang": "metal",
  "heart-point": "pop",
  "sporty-hop": "pop",
  "thumbs-in-belt": "country",
  "lasso-twirl": "country",
  "boot-scoot": "country",
  "night-fever": "disco",
  "the-bump": "disco",
  "chicken-dance": "shared"
};

const v = (unit, item, variant, verdict, line, reason, fix) => ({
  unit,
  genre: unit === "moves" ? MOVE_GENRE[item] : UNIT_GENRE[unit],
  item,
  variant,
  verdict,
  line,
  reason,
  ...(fix ? { fix } : {})
});

